def solve(n, s):
    if n % 2 != 0:
        return ":("

    # Count the number of '(' and ')' needed to balance the string
    open_needed = n // 2
    close_needed = n // 2

    # Count the number of '?' to ensure we can balance the string
    question_marks = s.count('?')

    # If the number of '?' is not enough to balance the string, return ":("
    if question_marks < abs(open_needed - close_needed):
        return ":("

    # Replace '?' with '(' or ')' to balance the string
    result = list(s)
    for i in range(n):
        if result[i] == '?':
            if open_needed > 0:
                result[i] = '('
                open_needed -= 1
            else:
                result[i] = ')'
                close_needed -= 1

    # Check if the resulting string is valid
    balance = 0
    for i in range(n):
        if result[i] == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return ":("
        if i < n - 1 and balance == 0:
            return ":("

    if balance != 0:
        return ":("

    return ''.join(result)

